-- Banque Téranga (fictive) · comptabilité générale · Oracle
-- À exécuter avec le compte TERANGA_GL (créé par make demo-data). Rejouable.
SET DEFINE OFF
WHENEVER SQLERROR CONTINUE
DROP TABLE ecritures PURGE;
DROP TABLE plan_comptable PURGE;
WHENEVER SQLERROR EXIT FAILURE
CREATE TABLE plan_comptable (
  compte VARCHAR2(6) PRIMARY KEY, libelle VARCHAR2(80) NOT NULL, classe CHAR(1) NOT NULL
);
CREATE TABLE ecritures (
  id NUMBER(10) PRIMARY KEY, date_ecriture DATE NOT NULL, journal VARCHAR2(4) NOT NULL,
  compte VARCHAR2(6) NOT NULL REFERENCES plan_comptable (compte), libelle VARCHAR2(80) NOT NULL,
  debit NUMBER(16,2) NOT NULL, credit NUMBER(16,2) NOT NULL, agence_code CHAR(3) NOT NULL, piece VARCHAR2(16) NOT NULL
);
CREATE INDEX ix_ecritures_date ON ecritures (date_ecriture);
COMMENT ON TABLE ecritures IS 'Écritures comptables du trimestre';
